import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { ArrowLeft, Save, Check, Search, Loader2, AlertCircle, CheckCircle2 } from 'lucide-react';
import { useShop } from '../context/ShopContext';
import { shopApi } from '../api/shop';

interface SelectedBundleLine {
  type: 'product' | 'course';
  id: string;
  variantId?: string;
  quantity: number;
}

const BundleEditor: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { storeInventory, courses, shopConfig, refreshAll, formatPrice } = useShop();

  const isEditing = Boolean(id);
  const activeCurrency = shopConfig.currency || 'IRR';

  const [loading, setLoading] = useState(isEditing);
  const [submitting, setSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [notice, setNotice] = useState<string | null>(null);

  const [title, setTitle] = useState('');
  const [subtitle, setSubtitle] = useState('');
  const [slug, setSlug] = useState('');
  const [sku, setSku] = useState('');
  const [price, setPrice] = useState('');
  const [originalPrice, setOriginalPrice] = useState('');
  const [discount, setDiscount] = useState('');
  const [domain, setDomain] = useState('fintech');
  const [visibility, setVisibility] = useState<'hidden' | 'catalog' | 'search' | 'featured'>('catalog');
  const [description, setDescription] = useState('');
  const [image, setImage] = useState('');
  const [tagsText, setTagsText] = useState('');
  const [featuresText, setFeaturesText] = useState('');

  const [selectedLines, setSelectedLines] = useState<SelectedBundleLine[]>([]);
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    if (!id) return;
    let mounted = true;
    const loadBundle = async () => {
      setLoading(true);
      setError(null);
      try {
        const item = await shopApi.getBundle(id);
        if (!mounted) return;
        if (!item) {
          setError('Bundle not found.');
          return;
        }
        setTitle(item.title || '');
        setSubtitle(item.subtitle || '');
        setSlug(item.slug || '');
        setSku(item.sku || '');
        setPrice(item.price ? String(item.price) : '');
        setOriginalPrice(item.originalPrice ? String(item.originalPrice) : '');
        setDiscount(item.discount !== undefined ? String(item.discount) : '');
        setDomain(item.domain || 'fintech');
        setVisibility(item.visibility || 'catalog');
        setDescription(item.description || '');
        setImage(item.image || '');
        setTagsText((item.tags || []).join(', '));
        setFeaturesText((item.features || []).join('\n'));

        // Reconstruct structured bundle lines from components or rawItems
        const initialLines: SelectedBundleLine[] = [];
        if (Array.isArray(item.components) && item.components.length > 0) {
          for (const c of item.components) {
            if (c.itemId || c.id) {
              initialLines.push({
                type: c.itemType === 'course' ? 'course' : 'product',
                id: String(c.itemId || c.id),
                variantId: c.variantId,
                quantity: Math.max(1, Math.min(100, Number(c.quantity) || 1)),
              });
            }
          }
        } else if (Array.isArray(item.rawItems) && item.rawItems.length > 0) {
          for (const r of item.rawItems) {
            if (typeof r === 'string') {
              initialLines.push({ type: 'product', id: r, quantity: 1 });
            } else if (r?.id || r?._id) {
              initialLines.push({
                type: r.type === 'course' ? 'course' : 'product',
                id: String(r.id || r._id),
                variantId: r.variantId,
                quantity: Math.max(1, Math.min(100, Number(r.quantity) || 1)),
              });
            }
          }
        }
        setSelectedLines(initialLines);
      } catch (err: any) {
        if (mounted) setError(err?.error || err?.message || 'Failed to load bundle.');
      } finally {
        if (mounted) setLoading(false);
      }
    };
    loadBundle();
    return () => {
      mounted = false;
    };
  }, [id]);

  // Combined selectable products AND courses
  const availableItems = useMemo(() => {
    const prodItems = storeInventory.map(p => ({ ...p, resolvedType: 'product' as const }));
    const courseItems = courses.map(c => ({ ...c, resolvedType: 'course' as const }));
    return [...prodItems, ...courseItems].filter(
      p => p.id !== id && p.title.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [storeInventory, courses, id, searchTerm]);

  const totalValue = useMemo(() => {
    const all = [...storeInventory, ...courses];
    return selectedLines.reduce((acc, line) => {
      const found = all.find(p => p.id === line.id || p.slug === line.id);
      return acc + (found?.price || 0) * line.quantity;
    }, 0);
  }, [selectedLines, storeInventory, courses]);

  const toggleSelection = (itemId: string, itemType: 'product' | 'course') => {
    setSelectedLines(prev => {
      const exists = prev.some(l => l.id === itemId);
      if (exists) return prev.filter(l => l.id !== itemId);
      return [...prev, { type: itemType, id: itemId, quantity: 1 }];
    });
  };

  const updateLineQuantity = (itemId: string, qty: number) => {
    const clamped = Math.max(1, Math.min(100, Math.round(qty) || 1));
    setSelectedLines(prev =>
      prev.map(l => (l.id === itemId ? { ...l, quantity: clamped } : l))
    );
  };

  const updateLineVariant = (itemId: string, variantId: string) => {
    setSelectedLines(prev =>
      prev.map(l =>
        l.id === itemId ? { ...l, variantId: variantId || undefined } : l
      )
    );
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setNotice(null);

    const parsedPrice = Math.round(Number(price));
    if (!title.trim() || title.trim().length < 3) {
      setError('Bundle title must be at least 3 characters.');
      return;
    }
    if (!description.trim() || description.trim().length < 10) {
      setError('Description must be at least 10 characters.');
      return;
    }
    if (!Number.isInteger(parsedPrice) || parsedPrice <= 0) {
      setError(`Bundle price must be a positive integer in ${activeCurrency}.`);
      return;
    }
    if (selectedLines.length === 0) {
      setError('Select at least one product or course to include in the bundle.');
      return;
    }

    const payload: Record<string, any> = {
      name: title.trim(),
      title: title.trim(),
      description: description.trim(),
      price: parsedPrice,
      currency: activeCurrency,
      type: 'bundle',
      domain,
      visibility,
      items: selectedLines.map(l => ({
        type: l.type,
        id: l.id,
        quantity: l.quantity,
        ...(l.variantId ? { variantId: l.variantId } : {}),
      })),
    };

    if (subtitle.trim()) payload.subtitle = subtitle.trim();
    if (slug.trim()) payload.slug = slug.trim().toLowerCase();
    if (sku.trim()) payload.sku = sku.trim();
    if (image.trim()) {
      payload.image = image.trim();
      payload.images = [image.trim()];
    }
    if (originalPrice.trim()) {
      const parsedOrig = Math.round(Number(originalPrice));
      if (!Number.isInteger(parsedOrig) || parsedOrig < parsedPrice) {
        setError('Original price must be an integer >= price.');
        return;
      }
      payload.originalPrice = parsedOrig;
    }
    if (discount.trim()) {
      const parsedDiscount = Number(discount);
      if (Number.isNaN(parsedDiscount) || parsedDiscount < 0 || parsedDiscount > 100) {
        setError('Discount must be between 0 and 100.');
        return;
      }
      payload.discount = parsedDiscount;
    }
    const tags = tagsText.split(',').map(s => s.trim()).filter(Boolean);
    if (tags.length > 0) payload.tags = tags;
    const features = featuresText.split('\n').map(s => s.trim()).filter(Boolean);
    if (features.length > 0) payload.features = features;

    setSubmitting(true);
    try {
      if (isEditing && id) {
        await shopApi.updateBundle(id, payload);
        setNotice('Bundle updated successfully.');
        await refreshAll();
      } else {
        const res = await shopApi.createBundle(payload);
        const createdId = res?.bundle?._id || res?.bundle?.id;
        await refreshAll();
        if (createdId) {
          navigate(`/admin/bundle/edit/${createdId}`, { replace: true });
          return;
        }
        navigate('/creator/catalog');
      }
    } catch (err: any) {
      const details = Array.isArray(err?.details) && err.details.length > 0
        ? err.details.map((d: any) => `${d.field || 'field'}: ${d.message}`).join('; ')
        : null;
      setError(details || err?.error || err?.message || 'Failed to save bundle.');
    } finally {
      setSubmitting(false);
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen pt-28 flex items-center justify-center text-slate-500">
        <Loader2 className="animate-spin text-emerald-600 mr-2" size={20} /> Loading bundle...
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#FBFBF9] dark:bg-[#090A0D] pb-20 pt-16">
      <header className="bg-white/90 dark:bg-[#101216]/90 backdrop-blur-md border-b border-[#E4E4DE] dark:border-[#222630] sticky top-16 z-40">
        <div className="max-w-6xl mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={() => navigate('/creator/catalog')}
              className="p-2 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition-colors text-slate-500"
            >
              <ArrowLeft size={18} />
            </button>
            <h1 className="text-base md:text-lg font-bold text-slate-900 dark:text-white">
              {isEditing ? 'Edit Bundle' : 'New Bundle'}
            </h1>
          </div>
          <button
            type="submit"
            form="bundle-form"
            disabled={submitting}
            className="px-4 py-2 bg-emerald-600 text-white rounded-lg font-semibold text-xs md:text-sm hover:bg-emerald-500 transition-colors flex items-center gap-2 disabled:opacity-50"
          >
            {submitting ? <Loader2 className="animate-spin" size={16} /> : <Save size={16} />}
            <span>{isEditing ? 'Save Bundle' : 'Create Draft'}</span>
          </button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 pt-6 space-y-4">
        {error && (
          <div className="p-4 rounded-xl bg-rose-500/10 border border-rose-500/30 text-xs text-rose-700 dark:text-rose-300 flex items-center gap-2">
            <AlertCircle size={15} className="shrink-0" />
            <span>{error}</span>
          </div>
        )}
        {notice && (
          <div className="p-4 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-xs text-emerald-700 dark:text-emerald-300 flex items-center gap-2">
            <CheckCircle2 size={15} className="shrink-0" />
            <span>{notice}</span>
          </div>
        )}
      </div>

      <form id="bundle-form" onSubmit={handleSave} className="max-w-6xl mx-auto px-4 py-6 grid grid-cols-1 lg:grid-cols-2 gap-8 items-start">
        <div className="bg-white dark:bg-[#111318] p-6 md:p-8 rounded-2xl border border-[#E4E4DE] dark:border-[#222630] space-y-5">
          <h2 className="text-xs font-mono font-bold uppercase text-slate-500 tracking-wider">
            Bundle Setup ({activeCurrency})
          </h2>

          <div className="space-y-4">
            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                Bundle Title *
              </label>
              <input
                required
                minLength={3}
                maxLength={200}
                type="text"
                value={title}
                onChange={e => setTitle(e.target.value)}
                className="w-full px-3.5 py-2.5 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white font-semibold"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                  Subtitle
                </label>
                <input
                  type="text"
                  maxLength={240}
                  value={subtitle}
                  onChange={e => setSubtitle(e.target.value)}
                  className="w-full px-3.5 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs text-slate-900 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                  URL Slug
                </label>
                <input
                  type="text"
                  value={slug}
                  onChange={e => setSlug(e.target.value)}
                  placeholder="auto if empty"
                  className="w-full px-3.5 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs font-mono text-slate-900 dark:text-white"
                />
              </div>
            </div>

            <div className="grid grid-cols-3 gap-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                  Price ({activeCurrency}) *
                </label>
                <input
                  required
                  type="number"
                  min={1}
                  step={1}
                  value={price}
                  onChange={e => setPrice(e.target.value)}
                  className="w-full px-3 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs font-mono tabular-nums text-slate-900 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                  Original Price
                </label>
                <input
                  type="number"
                  min={1}
                  step={1}
                  value={originalPrice}
                  onChange={e => setOriginalPrice(e.target.value)}
                  className="w-full px-3 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs font-mono tabular-nums text-slate-900 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                  Discount % (0–100)
                </label>
                <input
                  type="number"
                  min={0}
                  max={100}
                  value={discount}
                  onChange={e => setDiscount(e.target.value)}
                  className="w-full px-3 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs font-mono tabular-nums text-slate-900 dark:text-white"
                />
              </div>
            </div>

            <div className="p-3 rounded-xl bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] flex items-center justify-between text-xs">
              <span className="text-slate-500">Selected Components Reference Total</span>
              <span className="font-mono font-bold text-slate-900 dark:text-white line-through">
                {formatPrice(totalValue, activeCurrency)}
              </span>
            </div>

            <div className="grid grid-cols-3 gap-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">Domain</label>
                <select
                  value={domain}
                  onChange={e => setDomain(e.target.value)}
                  className="w-full px-3 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs text-slate-900 dark:text-white"
                >
                  <option value="fintech">fintech</option>
                  <option value="saas">saas</option>
                  <option value="commerce">commerce</option>
                  <option value="frontend">frontend</option>
                  <option value="software">software</option>
                  <option value="other">other</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">Visibility</label>
                <select
                  value={visibility}
                  onChange={e => setVisibility(e.target.value as any)}
                  className="w-full px-3 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs text-slate-900 dark:text-white"
                >
                  <option value="catalog">catalog</option>
                  <option value="search">search</option>
                  <option value="featured">featured</option>
                  <option value="hidden">hidden</option>
                </select>
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">SKU</label>
                <input
                  type="text"
                  value={sku}
                  onChange={e => setSku(e.target.value)}
                  className="w-full px-3 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs font-mono text-slate-900 dark:text-white"
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                Cover Image URI
              </label>
              <input
                type="url"
                value={image}
                onChange={e => setImage(e.target.value)}
                placeholder="https://..."
                className="w-full px-3.5 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs font-mono text-slate-900 dark:text-white"
              />
            </div>

            <div>
              <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                Description * (10–5,000 chars)
              </label>
              <textarea
                required
                minLength={10}
                rows={4}
                value={description}
                onChange={e => setDescription(e.target.value)}
                className="w-full px-3.5 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-sm text-slate-900 dark:text-white"
              />
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                  Tags (comma separated)
                </label>
                <input
                  type="text"
                  value={tagsText}
                  onChange={e => setTagsText(e.target.value)}
                  className="w-full px-3 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs text-slate-900 dark:text-white"
                />
              </div>
              <div>
                <label className="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1">
                  Features (one per line)
                </label>
                <textarea
                  rows={2}
                  value={featuresText}
                  onChange={e => setFeaturesText(e.target.value)}
                  className="w-full px-3 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs text-slate-900 dark:text-white"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Right: Component Selector (Products + Courses, with Quantity & Variant) */}
        <div className="bg-white dark:bg-[#111318] p-6 md:p-8 rounded-2xl border border-[#E4E4DE] dark:border-[#222630] flex flex-col lg:h-[calc(100vh-140px)] lg:sticky lg:top-24">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xs font-mono font-bold uppercase text-slate-500 tracking-wider">
              Bundle Items (Products &amp; Courses) *
            </h2>
            <span className="text-xs font-mono font-bold text-emerald-600 dark:text-emerald-400">
              {selectedLines.length} Selected
            </span>
          </div>

          <div className="relative mb-4">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={15} />
            <input
              type="text"
              placeholder="Search products and courses..."
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
              className="w-full pl-9 pr-4 py-2 bg-[#FBFBF9] dark:bg-[#090A0D] border border-[#E4E4DE] dark:border-[#222630] rounded-xl text-xs text-slate-900 dark:text-white"
            />
          </div>

          <div className="flex-1 overflow-y-auto space-y-2.5 pr-1">
            {availableItems.length > 0 ? (
              availableItems.map(item => {
                const selectedLine = selectedLines.find(l => l.id === item.id);
                const isSelected = Boolean(selectedLine);
                return (
                  <div
                    key={`${item.resolvedType}-${item.id}`}
                    className={`p-3 rounded-xl border transition-all space-y-2 ${
                      isSelected
                        ? 'bg-emerald-500/5 border-emerald-500/50'
                        : 'bg-[#FBFBF9] dark:bg-[#090A0D] border-[#E4E4DE] dark:border-[#222630]'
                    }`}
                  >
                    <div
                      onClick={() => toggleSelection(item.id, item.resolvedType)}
                      className="flex items-center gap-3 cursor-pointer"
                    >
                      <div
                        className={`w-5 h-5 rounded-md border flex items-center justify-center shrink-0 ${
                          isSelected
                            ? 'bg-emerald-600 border-emerald-600 text-white'
                            : 'border-slate-300 dark:border-slate-600'
                        }`}
                      >
                        {isSelected && <Check size={12} />}
                      </div>
                      <div className="flex-1 min-w-0">
                        <h4 className="font-bold text-slate-900 dark:text-white text-xs truncate">
                          {item.title}
                        </h4>
                        <div className="text-[11px] font-mono text-slate-500 uppercase">
                          {item.resolvedType} · {formatPrice(item.price, item.currency)}
                        </div>
                      </div>
                    </div>

                    {isSelected && selectedLine && (
                      <div className="pl-8 flex flex-wrap items-center gap-2 text-xs">
                        <label className="flex items-center gap-1.5 text-slate-500">
                          <span>Qty:</span>
                          <input
                            type="number"
                            min={1}
                            max={100}
                            value={selectedLine.quantity}
                            onChange={e => updateLineQuantity(item.id, Number(e.target.value))}
                            className="w-16 px-2 py-1 rounded border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] font-mono text-slate-900 dark:text-white"
                          />
                        </label>
                        {item.variants && item.variants.length > 0 && (
                          <select
                            value={selectedLine.variantId || ''}
                            onChange={e => updateLineVariant(item.id, e.target.value)}
                            className="flex-1 min-w-[140px] px-2 py-1 rounded border border-[#E4E4DE] dark:border-[#222630] bg-white dark:bg-[#111318] text-slate-900 dark:text-white"
                          >
                            <option value="">Default variant</option>
                            {item.variants.map((v: any) => (
                              <option key={v.id || v._id} value={v.id || v._id}>
                                {v.name}
                              </option>
                            ))}
                          </select>
                        )}
                      </div>
                    )}
                  </div>
                );
              })
            ) : (
              <div className="text-center py-10 text-slate-500 text-xs">
                No matching products or courses available.
              </div>
            )}
          </div>
        </div>
      </form>
    </div>
  );
};

export default BundleEditor;
